from solution import triangle_area
import math
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


positive_floats = st.floats(min_value=0.1, max_value=100.0, allow_nan=False, allow_infinity=False)
positive_numbers = st.one_of(
    st.integers(min_value=1, max_value=100),
    st.floats(min_value=0.1, max_value=100.0, allow_nan=False, allow_infinity=False),
)


def reference_area(a, b, c):
    if a + b <= c or a + c <= b or b + c <= a:
        return -1
    s = (a + b + c) / 2.0
    return round(math.sqrt(s * (s - a) * (s - b) * (s - c)), 2)


def test_example_3_4_5():
    assert triangle_area(3, 4, 5) == 6.00


def test_example_invalid():
    assert triangle_area(1, 2, 10) == -1


def test_degenerate_first_permutation():
    # a + b == c -> invalid
    assert triangle_area(1, 1, 2) == -1


def test_degenerate_second_permutation():
    # a + c == b -> invalid (strictly greater required)
    assert triangle_area(1, 2, 1) == -1


def test_degenerate_third_permutation():
    # b + c == a -> invalid
    assert triangle_area(2, 1, 1) == -1


def test_degenerate_float_second_permutation():
    assert triangle_area(1.5, 3.0, 1.5) == -1


def test_equilateral_unit():
    # s=1.5, area = sqrt(1.5*0.5**3) = sqrt(3)/4 ~= 0.433... -> 0.43
    assert triangle_area(1, 1, 1) == 0.43


def test_validity_matches_spec():
    # Heron check on a known 5-12-13 triangle: s=15, area=30
    assert triangle_area(5, 12, 13) == 30.0


@given(a=positive_numbers, b=positive_numbers, c=positive_numbers)
def test_validity_property(a, b, c):
    result = triangle_area(a, b, c)
    valid = (a + b > c) and (a + c > b) and (b + c > a)
    if not valid:
        assert result == -1
    else:
        assert result != -1
        assert result >= 0


@given(x=positive_floats, y=positive_floats)
def test_degenerate_equality_second_permutation_property(x, y):
    # a + c == b exactly must be invalid per spec (needs strictly greater)
    a = x
    c = y
    b = x + y
    assert triangle_area(a, b, c) == -1


@given(x=positive_floats, y=positive_floats)
def test_degenerate_equality_all_permutations_property(x, y):
    assert triangle_area(x, y, x + y) == -1
    assert triangle_area(x + y, x, y) == -1
    assert triangle_area(x, x + y, y) == -1


@given(a=positive_numbers, b=positive_numbers, c=positive_numbers)
def test_reference_model_equivalence(a, b, c):
    assert triangle_area(a, b, c) == reference_area(a, b, c)


@given(a=positive_numbers, b=positive_numbers, c=positive_numbers)
def test_symmetry_permutation_invariance(a, b, c):
    r1 = triangle_area(a, b, c)
    assert triangle_area(a, c, b) == r1
    assert triangle_area(b, a, c) == r1
    assert triangle_area(b, c, a) == r1
    assert triangle_area(c, a, b) == r1
    assert triangle_area(c, b, a) == r1


@given(a=positive_numbers, b=positive_numbers, c=positive_numbers)
def test_rounded_to_two_decimals(a, b, c):
    result = triangle_area(a, b, c)
    if result != -1:
        assert result == round(result, 2)


@given(a=positive_floats, b=positive_floats, c=positive_floats)
def test_strict_inequality_boundary(a, b, c):
    # If clearly invalid by a margin, must be -1; if clearly valid by margin, must not be -1
    assume(abs((a + b) - c) > 1e-6)
    assume(abs((a + c) - b) > 1e-6)
    assume(abs((b + c) - a) > 1e-6)
    result = triangle_area(a, b, c)
    valid = (a + b > c) and (a + c > b) and (b + c > a)
    if valid:
        assert result != -1
    else:
        assert result == -1


def test_just_valid_thin_triangle():
    # 2 + 3 > 4.999 so valid, small positive area, not -1
    r = triangle_area(2, 3, 4.999)
    assert r != -1
    assert r == reference_area(2, 3, 4.999)
    assert r > 0


def test_just_invalid_thin_triangle():
    assert triangle_area(2, 3, 5.0) == -1
    assert triangle_area(2, 3, 5.0001) == -1
